import json
DV = {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"}
STYLE = {"primary": {"labels": {"alignment": "left", "position": "bottom"}, "value": {"alignment": "right", "sizing": "auto"}}}

def metric(title, operation, field=None, x=0, y=0, w=12, h=5):
    m = {"empty_as_null": False, "operation": operation, "type": "primary"}
    if field:
        m["field"] = field
    return {
        "type": "vis",
        "grid": {"x": x, "y": y, "w": w, "h": h},
        "config": {
            "type": "metric", "title": title, "data_source": DV,
            "ignore_global_filters": False, "sampling": 1,
            "metrics": [m], "styling": STYLE,
        },
    }

def esql_xy(title, layer_type, query, x_col, y_col, x, y, w, h):
    return {
        "type": "vis",
        "grid": {"x": x, "y": y, "w": w, "h": h},
        "config": {
            "type": "xy", "title": title,
            "axis": {"x": {"scale": "ordinal"}, "y": {"anchor": "start", "scale": "linear", "title": {"visible": True}}},
            "layers": [{
                "type": layer_type,
                "data_source": {"type": "esql", "query": query},
                "ignore_global_filters": False, "sampling": 1,
                "x": {"column": x_col},
                "y": [{"axis_id": "y", "column": y_col}],
            }],
            "legend": {"placement": "outside", "position": "right", "visibility": "visible"},
            "styling": {"interpolation": "linear", "points": {"visibility": "auto"}},
        },
    }

panels = [
    metric("Total requests", "count", x=0, y=0),
    metric("Unique visitors", "unique_count", field="clientip", x=12, y=0),
    metric("Average response size (bytes)", "average", field="bytes", x=24, y=0),
    {
        "type": "vis",
        "grid": {"x": 36, "y": 0, "w": 12, "h": 5},
        "config": {
            "type": "markdown",
            "content": "Sample web traffic from `kibana_sample_data_logs`. 5xx spikes are monitored by the `EFF-9df6ad4d 5xx spike` alert rule.",
        },
    },
    esql_xy("Requests over time", "line",
            "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)",
            "BUCKET(@timestamp, 75, ?_tstart, ?_tend)", "count", x=0, y=5, w=48, h=10),
    esql_xy("Responses by status code", "bar",
            "FROM kibana_sample_data_logs | STATS count = COUNT() BY response.keyword | SORT count DESC | LIMIT 20",
            "response.keyword", "count", x=0, y=15, w=24, h=12),
    esql_xy("Requests by OS", "bar",
            "FROM kibana_sample_data_logs | STATS count = COUNT() BY machine.os.keyword | SORT count DESC | LIMIT 10",
            "machine.os.keyword", "count", x=24, y=15, w=24, h=12),
]

body = {
    "title": "EFF-9df6ad4d Web logs overview",
    "time_range": {"from": "now-7d", "to": "now"},
    "panels": panels,
}
print(json.dumps(body))
EOF
python3 $S/make_dashboard.py > $S/dashboard.json && H=(-H "kbn-xsrf: true" -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "Content-Type: application/json" -H "Elastic-Api-Version: 1"); curl -sS "${H[@]}" -X POST "$KIBANA_URL/api/dashboards" --data @$S/dashboard.json -o $S/dashboard_resp.json -w "%{http_code}\n"; python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); print(d.get("id") or d); print(d.get("message", "")); print(len(d.get("data",{}).get("panels",[])) if "data" in d else "")' $S/dashboard_resp.json

